values
  ('44dc02a8-6c3b-509f-b985-ad407a0f8277', '22222222-2222-2222-2222-222222222216', 'mcq', '车间共有40 人，某技术操作考核的平均成绩为80 分，其中男工平均 成绩为83 分，女工平均成绩为78 分.该车间有女工( )人.', '[{"key": "A", "text": "36"}, {"key": "B", "text": "30"}, {"key": "C", "text": "28"}, {"key": "D", "text": "24"}, {"key": "E", "text": "20"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, false, 23, null),
  ('17ce6aea-af5c-5379-b6a7-8686f3500cca', '22222222-2222-2222-2222-222222222216', 'mcq', '甲杯中有纯酒精12克，乙杯中有水15克，第一次，将甲杯中部分酒精 倒入乙杯中。第二次，将乙杯中部分溶液倒入甲杯中。这时，测得甲 杯中溶液浓度为50% ，乙杯中溶液浓度为25% 。则第二次操作中，乙 杯倒入甲杯溶液为( )克.（难）', '[{"key": "A", "text": "13"}, {"key": "B", "text": "14"}, {"key": "C", "text": "15"}, {"key": "D", "text": "16"}, {"key": "E", "text": "17"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, false, 24, null),
  ('d9d570e8-4ff7-5c52-9d3d-a5c1bf6510b9', '22222222-2222-2222-2222-222222222216', 'mcq', '某容器中装满了浓度为90%的酒精，倒出1 升后用水将容器注满，搅 拌均匀后又倒出1 升，再用水将容器注满.已知此时的酒精浓度为40%， 则该容器的容积为( ).', '[{"key": "A", "text": "2.5 升"}, {"key": "B", "text": "3 升"}, {"key": "C", "text": "3.5 升"}, {"key": "D", "text": "4.5 升"}, {"key": "E", "text": "4 升"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 12, false, 26, null),
  ('136b61e4-0da3-5727-a72e-8a5c67a64407', '22222222-2222-2222-2222-222222222216', 'mcq', '某班同学在一次测试中，平均成绩为75 分，其中男同学人数比女同学 人数多80%，而女同学的平均成绩比男同学的高20%，则女同学的平 均成绩为( ).', '[{"key": "A", "text": "83 分"}, {"key": "B", "text": "84 分"}, {"key": "C", "text": "85 分"}, {"key": "D", "text": "86 分"}, {"key": "E", "text": "87 分"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, false, 27, null),
  ('2d890606-cbda-5cd6-bcba-6d2a04122993', '22222222-2222-2222-2222-222222222216', 'mcq', '某人以6 公里/小时的平均速度上山，上山后立即以12 公里/小时的平 均速度原路返回，那么此人在往返过程中每小时平均所走的公里数为 ( ).', '[{"key": "A", "text": "9"}, {"key": "B", "text": "8"}, {"key": "C", "text": "7"}, {"key": "D", "text": "6"}, {"key": "E", "text": "5"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, false, 33, null),
  ('c39e51a6-660d-5e2f-84a6-3d196174e798', '22222222-2222-2222-2222-222222222216', 'mcq', '甲、乙两车同时从𝐴, 𝐵两地相向开出，甲车行驶速度为70km/h，乙车 每小时行驶62km/h，两辆车在离中点20km 处相遇，则𝐴, 𝐵两地相距 ( )km.', '[{"key": "A", "text": "660"}, {"key": "B", "text": "330"}, {"key": "C", "text": "300"}, {"key": "D", "text": "600"}, {"key": "E", "text": "570"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, false, 36, null),
  ('5b44d766-efe7-5ff4-b8d7-81079183b6df', '22222222-2222-2222-2222-222222222216', 'mcq', '甲、乙两列火车分别从𝐴城，𝐵城相向而行，第一次相遇在离𝐴地500 公 里处，相遇后，两列车继续前进，各自到达目的地后，又折回，第二 次相遇在离𝐵城300 公里处，问𝐴城，𝐵城相距( )公里.', '[{"key": "A", "text": "600"}, {"key": "B", "text": "800"}, {"key": "C", "text": "1000"}, {"key": "D", "text": "1200"}, {"key": "E", "text": "1500"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, false, 37, null),
  ('efcfd479-435e-5846-97ad-91a3d7a83fb1', '22222222-2222-2222-2222-222222222216', 'mcq', '甲、乙两人从同一地点出发，甲先出发10 分钟.若乙跑步追赶甲，则10 分钟追上；若乙骑车追赶甲，每分钟比跑步多行100 米，则5 分钟追 上.那么甲每分钟走的距离为( )米.', '[{"key": "A", "text": "50"}, {"key": "B", "text": "75"}, {"key": "C", "text": "100"}, {"key": "D", "text": "125"}, {"key": "E", "text": "150"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, false, 38, null),
  ('8a06d1b9-dafa-5f77-9f92-767d43d7d6b4', '22222222-2222-2222-2222-222222222216', 'mcq', '甲、乙两人同时从A 点出发,沿400 米跑道同向均匀行走,25 分钟后乙 比甲少走了一圈.若乙行走一圈需要8 分钟,则甲的速度是( )米/分钟.', '[{"key": "A", "text": "62"}, {"key": "B", "text": "65"}, {"key": "C", "text": "66"}, {"key": "D", "text": "67"}, {"key": "E", "text": "69"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, false, 39, null),
  ('91eba894-f34f-5f1d-a4dc-32114713a57c', '22222222-2222-2222-2222-222222222216', 'mcq', '已知船在静水中的速度为25 千米/小时，水流的速度为15 千米/小时， 则此船在相距80 千米的两地间往返一次所需要的时间是( )小时.', '[{"key": "A", "text": "8"}, {"key": "B", "text": "10"}, {"key": "C", "text": "12"}, {"key": "D", "text": "14"}, {"key": "E", "text": "16"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 23, false, 40, null),
  ('54fdf5bb-864f-5f54-842d-ea40f6b19bf3', '22222222-2222-2222-2222-222222222216', 'mcq', '一列火车长75 米，通过525 米长的桥梁需要40 秒，若以同样的速度 穿过300 米的隧道，则需要( )秒.', '[{"key": "A", "text": "20"}, {"key": "B", "text": "23"}, {"key": "C", "text": "25"}, {"key": "D", "text": "27"}, {"key": "E", "text": "28"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 25, false, 46, null),
  ('7dac912a-2128-5f59-9b69-c4545a3aa006', '22222222-2222-2222-2222-222222222216', 'mcq', '货车行驶72km用时1h，其速度𝑣与行驶时间𝑡的关系如图所示，则𝑣0 = ( )km/h.', '[{"key": "A", "text": "72"}, {"key": "B", "text": "80"}, {"key": "C", "text": "90"}, {"key": "D", "text": "95"}, {"key": "E", "text": "100"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 26, false, 49, null),
  ('fb0bf2ea-4ba5-58e7-acb5-b2e4049d6e70', '22222222-2222-2222-2222-222222222216', 'mcq', '一项工程甲、乙、丙三人合作需要15 天完成，如果乙休息2 天，丙就 要多做4 天，或者由甲、乙两人合作1 天，则这项工程由丙单独做需要 ( )天.', '[{"key": "A", "text": "40"}, {"key": "B", "text": "45"}, {"key": "C", "text": "50"}, {"key": "D", "text": "60"}, {"key": "E", "text": "75"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, false, 63, null),
  ('e5d10754-0933-5154-bfe5-37c7381d7bdf', '22222222-2222-2222-2222-222222222216', 'mcq', '某工程由甲公司承包需要60 天完成，由甲、乙两公司共同承包需要28 天完成，由乙、丙两公司共同承包需要35 天完成，则由丙公司承包完 成该工程需要的天数为( ).', '[{"key": "A", "text": "85"}, {"key": "B", "text": "90"}, {"key": "C", "text": "95"}, {"key": "D", "text": "10"}, {"key": "E", "text": "105"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, false, 64, null),
  ('877caa3c-4a38-5131-8d32-369f935db711', '22222222-2222-2222-2222-222222222216', 'mcq', '完成某项任务，甲单独做需要12 天，乙单独做需要6 天，丙单独做需 要24 天，现甲、乙、丙三人依次一日一轮地工作，则完成该项任务共 需的天数为( ).', '[{"key": "A", "text": "9 3 4"}, {"key": "B", "text": "10 1 4"}, {"key": "C", "text": "10 3 4"}, {"key": "D", "text": "10"}, {"key": "E", "text": "11 1 4 你的坚持，终将美好！ 23 你的坚持，终将美好！ 24 三、牛吃草公式 𝑦= (𝑁−𝑥) × 𝑇"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, false, 65, null),
  ('7a506056-b918-5065-9da4-3fc1dd950b74', '22222222-2222-2222-2222-222222222216', 'mcq', '牧场上一片青草，每天牧草都均匀生长。这片牧草可供100 头牛吃20 天，或者可供150 头牛吃10 天。则这片牧场可供250 头牛吃( )天.', '[{"key": "A", "text": "5"}, {"key": "B", "text": "6"}, {"key": "C", "text": "7"}, {"key": "D", "text": "8"}, {"key": "E", "text": "9"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, false, 74, null),
  ('32d1fc27-ea0f-5ba9-948a-9725ea8206e2', '22222222-2222-2222-2222-222222222216', 'mcq', '某道路一侧原有路灯106 盏，道路两端均设有路灯，相邻两盏灯的距 离为36m，现将原有路灯全部换为新型节能灯，两灯距离变为70m， 道路两端依旧各装一盏路灯，布局不超出原道路范围，则道路一侧共需 新型节能灯( )盏.', '[{"key": "A", "text": "54"}, {"key": "B", "text": "55"}, {"key": "C", "text": "108"}, {"key": "D", "text": "110"}, {"key": "E", "text": "112"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 10, false, 75, null),
  ('acd47185-00ae-504c-a054-8911129eb138', '22222222-2222-2222-2222-222222222216', 'mcq', '将一批树苗种在一个正方形花园的边上，四角都种.如果每隔3m 种一 棵，那么剩下10 棵树苗；如果每隔2m 种一棵，那么恰好种满正方形 的3 条边，则这批树苗有( )棵.', '[{"key": "A", "text": "54"}, {"key": "B", "text": "60"}, {"key": "C", "text": "70"}, {"key": "D", "text": "82"}, {"key": "E", "text": "94"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 10, false, 76, null),
  ('aa0f575c-ef67-572a-9405-f120083037fd', '22222222-2222-2222-2222-222222222216', 'mcq', '某单位有职工40 人，其中参加计算机考核的有31 人，参加外语考核 的有20 人，有8 人没有参加任何一种考核，则同时参加两项考核的职 工有( )人.', '[{"key": "A", "text": "10"}, {"key": "B", "text": "13"}, {"key": "C", "text": "15"}, {"key": "D", "text": "19"}, {"key": "E", "text": "20"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, false, 80, null),
  ('1a6da806-0d0b-54dc-aec5-e879e01e25d2', '22222222-2222-2222-2222-222222222216', 'mcq', '某单位有240 名员工，其中订阅𝐴期刊的有125 人，订阅𝐵期刊的有 126 人，订阅𝐶期刊的有135 人，订阅𝐴、𝐵期刊的有57 人，订阅𝐴、𝐶 期刊的有73 人，订阅3 种期刊的有31 人，此外，还有17 人没有订 阅这三种期刊中的任何一种。则订阅𝐵、𝐶期刊的有( )人.', '[{"key": "A", "text": "57"}, {"key": "B", "text": "64"}, {"key": "C", "text": "69"}, {"key": "D", "text": "78"}, {"key": "E", "text": "81"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, false, 81, null),
  ('104cce50-d834-54d4-bc6c-f0a0a499abc6', '22222222-2222-2222-2222-222222222216', 'mcq', '某公司的员工中，拥有本科毕业证、计算机等级证、汽车驾驶证的人数 分别为130，110，90，又知只有一种证的人数为140，三证齐全的人 数为30，则恰有双证的人数为( ).', '[{"key": "A", "text": "45"}, {"key": "B", "text": "50"}, {"key": "C", "text": "52"}, {"key": "D", "text": "65"}, {"key": "E", "text": "100"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, false, 82, null),
  ('b866150d-4383-5914-a101-537de5209254', '22222222-2222-2222-2222-222222222216', 'mcq', '某公司用1 万元购买了价格分别是1750 元和950 元的甲、乙两种办 公设备，则购买的甲、乙办公设备的件数分别为( ).', '[{"key": "A", "text": "3,5"}, {"key": "B", "text": "5,3"}, {"key": "C", "text": "4,4"}, {"key": "D", "text": "2,6"}, {"key": "E", "text": "6,2"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, false, 83, null),
  ('f3ad9eb8-3315-5965-bfc8-eb38d5a0a1dc', '22222222-2222-2222-2222-222222222216', 'mcq', '某单位向希望工程捐款，其中部门领导每人捐50 元，普通员工每人捐 20 元，某部门所有人员共捐款320 元，已知该部门总人数超过10 人， 则该部门可能有( )名部门领导.', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}, {"key": "E", "text": "5"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, false, 84, null),
  ('dd33d3d3-8e43-517b-a92f-d6b64c9adabf', '22222222-2222-2222-2222-222222222216', 'mcq', '有271 位游客欲乘大、小两种客车旅游，已知大客车有37 个座位，小 客车有20 个座位. 为保证每位游客均有座位，且车上没有空座位，则 需要大客车的辆数是( ).', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}, {"key": "E", "text": "5"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 17, false, 85, null),
  ('83d9c6c4-7c51-5127-aaf8-4392ea10530f', '22222222-2222-2222-2222-222222222216', 'mcq', '某自来水公司的水费计算方法如下：每户每月用水不超过5 吨的，每 吨收费4 元，超过5 吨的，每吨收取较高标准的费用.已知9 月份张家 的用水量比李家的用水量多50%，张家和李家的水费分别是90 元和 55 元，则用水量超过5 吨的收费标准是( )元/吨.', '[{"key": "A", "text": "5"}, {"key": "B", "text": "5.5"}, {"key": "C", "text": "6"}, {"key": "D", "text": "6.5"}, {"key": "E", "text": "7"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, false, 86, null)
